    NewCustomProvider.Oidc("custom:mycompany", "My Company SSO", clientId: "id", clientSecret: "secret",
        issuer: new Uri("https://accounts.mycompany.com")),
    new CustomProviderOptions { Scopes = new[] { "email", "profile" } });

